#!/bin/bash
# Владелец файла — разработчик CI (MEE-166).
#
# Выносит в аннотацию хвост журнала, когда шаг упал ДО того, как разбор графа
# успел сказать хоть слово: свой вердикт — и удачный, и с нарушениями — выносит
# сам symbol-graph-surface.py. Без этого причина такого отказа видна только тому,
# у кого есть доступ к хранилищу логов Actions, а у читателя PR его может не быть.
# Ровно так и вышло на первом прогоне PR #12: оболочка умерла на первой строке
# шага с кодом 2, и в аннотациях не было ничего, кроме самого кода.
set -o pipefail
title="$1"
status="$2"
log="$3"

# Перевод строки в аннотации кодируется %0A, сам знак процента — %25.
encode() {
  awk '{ gsub(/%/, "%25"); printf "%s%%0A", $0 }' | cut -c1-4000
}

if [ "$status" -ne 0 ]; then
  printf '::error title=%s::шаг завершился с кодом %s. Хвост журнала:%%0A%s\n' \
    "$title" "$status" "$(tail -n 40 "$log" | encode)"
fi
